import React, { useState } from "react";
import { login, uploadFile, analyzeText, analyzeStored } from "./api";

function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [token, setToken] = useState(null);
  const [file, setFile] = useState(null);
  const [storedFilename, setStoredFilename] = useState(null);
  const [text, setText] = useState("");
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  async function handleLogin(e) {
    e.preventDefault();
    setError(null);
    try {
      const res = await login(email, password);
      setToken(res.data.access_token);
    } catch (err) {
      setError(err?.response?.data?.detail || "Login failed");
    }
  }

  async function handleUpload(e) {
    e.preventDefault();
    if (!file) return setError("Select a file first");
    setLoading(true);
    try {
      const res = await uploadFile(file, token);
      setStoredFilename(res.data.stored_filename);
    } catch (err) {
      setError(err?.response?.data?.detail || "Upload failed");
    } finally {
      setLoading(false);
    }
  }

  async function handleAnalyzeText(e) {
    e.preventDefault();
    if (!text) return setError("Enter text to analyze");
    setLoading(true);
    try {
      const res = await analyzeText(text, token);
      setResults(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || "Analyze failed");
    } finally {
      setLoading(false);
    }
  }

  async function handleAnalyzeStored(e) {
    e.preventDefault();
    if (!storedFilename) return setError("No uploaded file stored");
    setLoading(true);
    try {
      const res = await analyzeStored(storedFilename, token);
      setResults(res.data);
    } catch (err) {
      setError(err?.response?.data?.detail || "Analyze failed");
    } finally {
      setLoading(false);
    }
  }

  // -------------------------------
  // LOGIN SCREEN
  // -------------------------------
  if (!token) {
    return (
      <div style={{ padding: 20, maxWidth: 600, margin: "auto" }}>
        <h2>🔐 Legal AI Analyzer — Login</h2>
        <form onSubmit={handleLogin}>
          <div>
            <label>Email</label><br />
            <input
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={{ width: "100%", marginBottom: 10 }}
            />
          </div>
          <div>
            <label>Password</label><br />
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{ width: "100%", marginBottom: 10 }}
            />
          </div>
          <button type="submit">Login</button>
          {error && <p style={{ color: "red" }}>{error}</p>}
        </form>
      </div>
    );
  }

  // -------------------------------
  // MAIN APP
  // -------------------------------
  return (
    <div style={{ padding: 20, maxWidth: 900, margin: "auto", fontFamily: "Arial, sans-serif" }}>
      <h2>⚖️ Legal AI Document Analyzer</h2>
      <p>Logged in as: <b>{email}</b></p>

      {/* Upload Section */}
      <section style={{ marginBottom: 20 }}>
        <h3>📂 Upload document</h3>
        <input type="file" onChange={(e) => setFile(e.target.files[0])} />
        <button onClick={handleUpload} disabled={loading || !file}>Upload & Encrypt</button>
        {storedFilename && <div>Stored as: <code>{storedFilename}</code></div>}
      </section>

      {/* Analyze Section */}
      <section style={{ marginBottom: 20 }}>
        <h3>🧠 Analyze Uploaded File</h3>
        <button onClick={handleAnalyzeStored} disabled={loading || !storedFilename}>
          Analyze Uploaded File
        </button>
      </section>

      {/* Text Analysis */}
      <section style={{ marginBottom: 20 }}>
        <h3>✍️ Analyze Pasted Text</h3>
        <textarea
          value={text}
          onChange={(e) => setText(e.target.value)}
          rows={8}
          style={{ width: "100%", marginBottom: 10 }}
        />
        <div>
          <button onClick={handleAnalyzeText} disabled={loading || !text}>
            Analyze Text
          </button>
        </div>
      </section>

      {/* Status */}
      {loading && <p>⏳ Working…</p>}
      {error && <p style={{ color: "red" }}>{error}</p>}

      {/* Results */}
      {results && (
        <section style={{ marginTop: 30, background: "#f8f8f8", padding: 20, borderRadius: 12 }}>
          <h3>📊 Analysis Results</h3>

          <h4>📝 Summary</h4>
          <p style={{ whiteSpace: "pre-wrap" }}>{results.summary}</p>

          <h4>⚖️ Overall Risk</h4>
          <p>
            <b>Level:</b>{" "}
            <span style={{
              color:
                results.overall_risk_level === "High"
                  ? "red"
                  : results.overall_risk_level === "Medium"
                  ? "orange"
                  : "green",
              fontWeight: "bold",
            }}>
              {results.overall_risk_level}
            </span>{" "}
            ({Math.round(results.overall_risk_score * 100)}%)
          </p>

          {results.detected_risks && results.detected_risks.length > 0 && (
            <>
              <h4>🚨 Detected Risk Indicators</h4>
              <ul>
                {results.detected_risks.map((risk, i) => (
                  <li key={i}>{risk}</li>
                ))}
              </ul>
            </>
          )}

          {results.recommendations && results.recommendations.length > 0 && (
            <>
              <h4>🛠️ Recommendations</h4>
              <ul>
                {results.recommendations.map((rec, i) => (
                  <li key={i}>{rec}</li>
                ))}
              </ul>
            </>
          )}
        </section>
      )}
    </div>
  );
}

export default App;
